import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log


def test_parse_skips_comments_and_blanks_and_strips_fields():
    lines = ["", " \t", "  # ignored", " a , 2 , 0 ", " b , 3 , "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,not-a-day,0"])
def test_parse_errors_include_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["# comment", "a,1,1", "", bad_line])


def test_dedupe_keeps_last_input_for_duplicate_id_then_sorts():
    events = parse_transcript_log(["b,8,1", "c,3,1", "b,1,0", "a,1,1"])
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]


def test_daily_counts_cover_only_inclusive_range():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,3,", "e,4,1", "f,5,1"])
    assert daily_flag_counts(events, 2, 4) == [2, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []

